tool_input.new_string:
/* 仅拍照场景（如求援现场照片）强制调起相机，不再允许从相册选择 */
const sourceType: Array<'camera' | 'album'> = props.cameraOnly ? ['camera'] : ['camera', 'album']
uni.chooseImage({ count: 6 - store.items.length, sizeType: ['compressed'], sourceType, success: async result => { try { await store.add(result.tempFilePaths as string[]) } catch (error) { uni.showToast({ title: error instanceof Error ? error.message : '照片保存失败', icon: 'none' }) } }, fail: result => { if (!result.errMsg.includes('cancel')) uni.showToast({ title: props.cameraOnly ? '无法拍照，请检查相机权限' : '无法选择照片，请检查相册权限', icon: 'none' }) } })
